        this.sheetId = sheetId;
        this.user = user;
        this.role = role.key();
    }

    public String getUser() {
        return user;
    }

    public Role getRole() {
        return Role.of(role);
    }

    public void setRole(Role role) {
        this.role = role.key();
    }

    public String getSheetId() {
        return sheetId;
    }
}
