import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Sign-in by name only: the name is checked and echoed back trimmed. */
@RestController
@RequestMapping("/api/session")
public class SessionController {

    public record SignIn(@NotBlank @Size(max = 100) String name) {
    }

    public record SessionView(String name) {
    }

    @PostMapping
    public SessionView signIn(@Valid @RequestBody SignIn body) {
        return new SessionView(body.name().trim());
    }
}
package net.officefloor.hq.app.settings;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface SheetRoleRepository extends JpaRepository<SheetRole, Long> {

    /** The sheet's roles, by user name. */
    List<SheetRole> findBySheetIdOrderByUserAsc(String sheetId);

    Optional<SheetRole> findBySheetIdAndUser(String sheetId, String user);
}
-- A rate saved with a from-date on or after the sheet's today is forward-only: it applies only to
-- claims added after it was saved. Such a rate (version) keeps the highest claim id there was when
-- it was saved; a claim applies it only when it was added after that (by its own id, or for a copy
-- in a clone of a sheet the id of the claim it copies). Null: the rate applies to every claim.
ALTER TABLE rate ADD COLUMN after_claim BIGINT;
-- The claim a copy in a clone was copied from was added as; null for a claim added on its sheet
-- (it was added as its own id).
ALTER TABLE claim ADD COLUMN added BIGINT;
-- The versions a claim added before a forward-only rate's newest version falls back to, newest
-- first: each forward-only one, up to and including the first that applies to every claim.
CREATE TABLE rate_earlier (
    rate_id     BIGINT        NOT NULL REFERENCES rate (id),
    position    INTEGER       NOT NULL,
    pct         DECIMAL(5, 2) NOT NULL,
    to_date     DATE,
    after_claim BIGINT,
    PRIMARY KEY (rate_id, position)
);
-- A third role, viewer: sees the sheet and changes nothing. The role's check is rebuilt to allow it.
CREATE TABLE sheet_role_new (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer'))
);
INSERT INTO sheet_role_new (id, sheet_id, user_name, role) SELECT id, sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

